INSERT INTO `assessment_traits` VALUES ('A','tier1_riasec','Artistic (क्रिएटर / रचनात्मक)','कलात्मक / रचनात्मक','interest','Creative self-expression, design, media, performance, and imaginative storytelling.','कला, डिजाइन, संगीत, लेखन और अभिव्यक्ति।','🎨','#9333ea'),('C','tier1_riasec','Conventional (ऑर्गनाइज़र / संगठक)','संगठनात्मक / व्यवस्थित','interest','Systematic organization, precise records, data accuracy, and structured workflows.','सुव्यवस्थित प्रणाली, रिकॉर्ड-कीपिंग और सटीकता।','📋','#0d9488'),('E','tier1_riasec','Enterprising (लीडर / उद्यमी)','उद्यमी / मार्गदर्शक','interest','Leadership, persuasion, business growth, risk-taking, and strategic initiative.','नेतृत्व, व्यापार, नई योजनाएं और प्रभावशीलता।','⚡','#d97706'),('ENABLER_ANXIETY','mental_health','Academic Anxiety','शैक्षणिक तनाव व चिंता','wellbeing','Exam stress, performance fear, and self-doubt management.','परीक्षा का तनाव, प्रदर्शन की चिंता और आत्म-संदेह।','🧘','#ef4444'),('ENABLER_RESILIENCE','mental_health','Mental Resilience','मानसिक लचीलापन व धैर्य','wellbeing','Bouncing back from setbacks, emotional perseverance, and optimism.','विपरीत परिस्थितियों में पुनः उठ खड़े होने का साहस।','💪','#10b981'),('ENABLER_SELF_EFFICACY','mental_health','Self-Efficacy','आत्म-प्रभावकारिता व विश्वास','wellbeing','Belief in one\'s own abilities to accomplish goals and overcome barriers.','कठिनाइयों से पार पाने का आत्मविश्वास।','🌟','#f59e0b'),('I','tier1_riasec','Investigative (थिंकर / शोधकर्ता)','विश्लेषणात्मक / शोधकर्ता','interest','Analytical observation, scientific research, data exploration, and problem solving.','वैज्ञानिक अनुसंधान, विचारशीलता और तार्किक विश्लेषण।','🔬','#2563eb'),('OCEAN_A','tier3_ocean','Agreeableness','सहानुभूति व सहयोग','personality','Empathy, cooperative teamwork, trust, and constructive conflict resolution.','सहयोग, संवेदनशीलता और सामंजस्य।','❤️','#ec4899'),('OCEAN_C','tier3_ocean','Conscientiousness','कर्तव्यनिष्ठा और अनुशासन','personality','Self-discipline, organization, goal focus, and dependable follow-through.','अनुशासन, योजनाबद्धता और जिम्मेदार कार्यशैली।','🎯','#10b981'),('OCEAN_E','tier3_ocean','Extraversion','बहिर्मुखता व सामाजिक ऊर्जा','personality','Sociability, assertiveness, team enthusiasm, and expressive communication.','सामाजिक संवाद, उत्साह और टीम में अग्रणी भूमिका।','🗣️','#f59e0b'),('OCEAN_N','tier3_ocean','Emotional Stability','भावनात्मक स्थिरता व संतुलन','personality','Calmness under pressure, resilience to anxiety, and steady demeanor.','तनाव में शांति, धैर्य और संतुलित दृष्टिकोण।','🛡️','#3b82f6'),('OCEAN_O','tier3_ocean','Openness to Experience','नए अनुभवों के प्रति खुलापन','personality','Curiosity, intellectual imagination, and appreciation for art and innovation.','नवाचार, कल्पना और नई चीजें सीखने की उत्सुकता।','💡','#8b5cf6'),('R','tier1_riasec','Realistic (डूअर / व्यावहारिक)','व्यावहारिक / कार्यकुशल','interest','Hands-on practical work with tools, machines, animals, or outdoor environments.','औजारों, मशीनों, और प्रकृति के साथ व्यावहारिक कार्य।','🔧','#c9432a'),('S','tier1_riasec','Social (हेल्पर / सामाजिक)','सामाजिक / सहायक','interest','Helping, teaching, mentoring, healthcare, and building community harmony.','दूसरों को सिखाना, सहायता करना और समाज कल्याण।','🤝','#16a34a'),('TAMANNA_AR','tier2_tamanna','Aptitude Reasoning (समग्र तार्किक योग्यता)','समग्र तार्किक योग्यता','aptitude','Deductive reasoning and critical hypothesis testing.','निगमनात्मक तर्क और समस्या समाधान।','🧠','#0284c7'),('TAMANNA_LA','tier2_tamanna','Language Aptitude (भाषा योग्यता)','भाषा योग्यता','aptitude','Vocabulary mastery, verbal reasoning, and linguistic precision.','शब्दावली, भाषा समझ और अभिव्यक्ति क्षमता।','📖','#2563eb'),('TAMANNA_MA','tier2_tamanna','Mechanical Aptitude (यांत्रिक योग्यता)','यांत्रिक योग्यता','aptitude','Understanding mechanical motion, levers, gears, and physical forces.','भौतिक बल, पुर्जे और यांत्रिक सिद्धांतों की समझ।','⚙️','#ea580c'),('TAMANNA_NA','tier2_tamanna','Numerical Aptitude (संख्यात्मक योग्यता)','संख्यात्मक योग्यता','aptitude','Arithmetic calculations, data analysis, and mathematical logic.','गणितीय गणना, डेटा विश्लेषण और तर्क।','🔢','#059669'),('TAMANNA_PA','tier2_tamanna','Perceptual Aptitude (अवधारणात्मक योग्यता)','अवधारणात्मक योग्यता','aptitude','Speed and accuracy in identifying fine visual details and symbols.','विवरणों और संकेतों को तेजी से पहचानने की क्षमता।','👁️','#db2777'),('TAMANNA_SA','tier2_tamanna','Spatial Aptitude (स्थानिक योग्यता)','स्थानिक योग्यता','aptitude','Mental visualization, 3D structures, and geometric relationships.','3D संरचनाएं, रेखाचित्र और दिशा समझ।','📐','#7c3aed'),('TAMANNA_VA','tier2_tamanna','Abstract Reasoning (अमूर्त तर्क)','अमूर्त तर्क','aptitude','Identifying logical patterns, sequences, and conceptual relationships.','तार्किक पैटर्न, आकृतियों और संबंधों को समझना।','🧩','#4f46e5');
