INSERT INTO `assessments` VALUES ('mental_health','mental_health','Emotional Resilience & Well-being','भावनात्मक लचीलापन और तनाव प्रबंधन (12 प्रश्न)','Identify academic stress levels, self-efficacy, emotional coping mechanisms, and support readiness.',8,12,5,1),('tier1_quick_riasec','tier1_quick_riasec','Quick RIASEC Career Pulse (Fast-Track)','त्वरित करियर पल्स - आरआईएएसईसी (24 प्रश्न)','24 rapid situational items (4 per domain) designed for students seeking quick 5-min initial career interest orientation.',5,24,2,1),('tier1_riasec','tier1_riasec','Comprehensive Holland RIASEC Battery','विस्तृत हॉलैंड आरआईएएसईसी रुचि इन्वेंट्री (42 प्रश्न)','Discover your top career interest clusters with the highest precision 42-question battery across 6 core domains.',10,42,1,1),('tier2_tamanna','tier2_tamanna','TAMANNA Multi-Aptitude Battery','तमन्ना बहु-योग्यता बैटरी (28 प्रश्न)','NCERT & CBSE standardized aptitude assessment across 7 essential cognitive and perceptual dimensions.',15,28,3,1),('tier3_ocean','tier3_ocean','Big Five Personality (OCEAN)','बिग फाइव व्यक्तित्व (20 प्रश्न)','Evaluate your core behavioral tendencies, teamwork style, stress tolerance, and intellectual openness.',10,20,4,1);
