--
-- Table structure for table `careers`
--

DROP TABLE IF EXISTS `careers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `careers` (
  `id` varchar(64) NOT NULL,
  `title` varchar(128) NOT NULL,
  `title_hi` varchar(128) NOT NULL,
  `sector_id` varchar(64) NOT NULL,
  `icon` varchar(32) DEFAULT '',
  `overview` text DEFAULT NULL,
  `overview_hi` text DEFAULT NULL,
  `min_salary_lpa` decimal(5,2) DEFAULT 3.00,
  `max_salary_lpa` decimal(5,2) DEFAULT 12.00,
  `required_education` varchar(128) DEFAULT '',
  `required_education_hi` varchar(128) DEFAULT '',
  `stream_preferred` varchar(64) DEFAULT 'general',
  `entrance_exams_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`entrance_exams_json`)),
  `riasec_weights_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`riasec_weights_json`)),
  `aptitude_weights_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`aptitude_weights_json`)),
  `interest_tags_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`interest_tags_json`)),
  `roadmap_steps_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`roadmap_steps_json`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_career_sector` (`sector_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

