--
-- Table structure for table `student_assessment_sessions`
--

DROP TABLE IF EXISTS `student_assessment_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_assessment_sessions` (
  `id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `tier_code` varchar(32) NOT NULL,
  `tier_title` varchar(64) DEFAULT '',
  `status` enum('in_progress','completed','abandoned') NOT NULL DEFAULT 'in_progress',
  `total_questions` int(11) NOT NULL DEFAULT 0,
  `answered_questions` int(11) NOT NULL DEFAULT 0,
  `score_percentage` int(11) DEFAULT 0,
  `responses_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'All question answers for this tier in 1 clean JSON map {qId: answer}' CHECK (json_valid(`responses_json`)),
  `tier_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Computed trait sub-scores for this tier' CHECK (json_valid(`tier_scores_json`)),
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_tier` (`user_id`,`tier_code`),
  KEY `idx_session_user` (`user_id`),
  KEY `idx_session_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

