--
-- Table structure for table `student_career_matches`
--

DROP TABLE IF EXISTS `student_career_matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_career_matches` (
  `user_id` varchar(64) NOT NULL,
  `top_career_1` varchar(128) DEFAULT '' COMMENT '1st Recommended Career Title',
  `top_career_1_hi` varchar(128) DEFAULT '' COMMENT '1st Recommended Career Hindi',
  `top_career_1_fit` int(11) DEFAULT 0 COMMENT '1st Match Fit %',
  `top_career_1_sector` varchar(64) DEFAULT '' COMMENT '1st Match Sector',
  `top_career_2` varchar(128) DEFAULT '' COMMENT '2nd Recommended Career Title',
  `top_career_2_hi` varchar(128) DEFAULT '' COMMENT '2nd Recommended Career Hindi',
  `top_career_2_fit` int(11) DEFAULT 0 COMMENT '2nd Match Fit %',
  `top_career_3` varchar(128) DEFAULT '' COMMENT '3rd Recommended Career Title',
  `top_career_3_hi` varchar(128) DEFAULT '' COMMENT '3rd Recommended Career Hindi',
  `top_career_3_fit` int(11) DEFAULT 0 COMMENT '3rd Match Fit %',
  `matches_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Full ranked list of career recommendations with why-reasons and details' CHECK (json_valid(`matches_json`)),
  `total_matches` int(11) DEFAULT 0,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`),
  KEY `idx_top1_fit` (`top_career_1_fit`),
  KEY `idx_top1_sector` (`top_career_1_sector`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

