--
-- Table structure for table `student_trait_scores`
--

DROP TABLE IF EXISTS `student_trait_scores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_trait_scores` (
  `user_id` varchar(64) NOT NULL,
  `holland_code` varchar(16) DEFAULT 'RIA',
  `top_trait_1` varchar(32) DEFAULT '',
  `top_trait_2` varchar(32) DEFAULT '',
  `top_trait_3` varchar(32) DEFAULT '',
  `riasec_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'RIASEC trait percentages' CHECK (json_valid(`riasec_scores_json`)),
  `tamanna_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'TAMANNA aptitude percentages' CHECK (json_valid(`tamanna_scores_json`)),
  `ocean_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Big Five OCEAN percentages' CHECK (json_valid(`ocean_scores_json`)),
