--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` varchar(64) NOT NULL,
  `role` enum('student','parent','teacher','counselor','school_admin','super_admin') NOT NULL DEFAULT 'student',
  `email` varchar(128) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `full_name` varchar(128) NOT NULL,
  `grade_level` varchar(32) DEFAULT '10',
  `school_name` varchar(192) DEFAULT 'Government High School',
  `education_status` varchar(32) DEFAULT 'pursuing',
  `city` varchar(128) DEFAULT '',
  `stream` varchar(64) DEFAULT 'general',
  `role_model_archetype` varchar(64) DEFAULT 'tech',
  `role_model_name` varchar(128) DEFAULT '',
  `dream_impact` text DEFAULT NULL,
  `aspiration` text DEFAULT NULL,
  `interest_tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`interest_tags`)),
  `work_style` varchar(64) DEFAULT 'analytical',
  `saved_careers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`saved_careers`)),
  `finalized_career` varchar(128) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_users_role` (`role`),
  KEY `idx_users_grade` (`grade_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
